style.css:
@-moz-document domain("roblox.com") {
/* Força a imagem a ficar no fundo absoluto de tudo */
    html {
        background: #0d1b2a url('https://alphacoders.com') no-repeat center center fixed !important;
        background-size: cover !important;
    }
    
    /* Remove as cores sólidas que o Roblox joga por cima */
    body, 
    .dark-theme, 
    .light-theme, 
    #container-main, 
    .main-layout, 
    .content, 
    #main-body, 
    .wrap,
    .container-list,
    #wrap {
        background: transparent !important;
        background-color: transparent !important;
    }
    
    /* Topbar com as cores do Invencível */
    .header-2018, .navigation .rbx-header {
        background-color: #1a4fa0 !important;
        border-bottom: 4px solid #f6cc16 !important;
    }
    
    /* Deixa as caixas de servidores e amigos visíveis com fundo escuro transparente */
    .section-content, 
    .container-main, 
    .profile-header, 
    .game-card, 
    .server-list-container,
    .stack-list,
    .card-list {
        background: rgba(13, 27, 42, 0.85) !important;
        border-radius: 8px !important;
        border: 1px solid #f6cc16 !important;
    }
    
    /* Cores dos textos e links */
    h1, h2, h3, .text-title, .text-name, .text-description, .text {
        color: #ffffff !important;
    }
    
    a, .text-link {
        color: #f6cc16 !important;
    }
    
    /* Botões */
    .btn-common-play-large, .btn-to-robux, .btn-full-width, .btn-control-sm {
        background-color: #e63946 !important;
        border: none !important;
        color: white !important;
    }
}
